import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Dropdown from 'flarum/common/components/Dropdown';
import Icon from 'flarum/common/components/Icon';
import loadAllBadges from '../utils/loadBadges';
export default class BadgeSelector extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    this.loaded = false;

    // Load badges
    loadAllBadges(() => this.loaded = true);
  }
  view() {
    if (!this.loaded) {
      return m("div", {
        className: "Form-group"
      }, m("label", null, this.attrs.label), m(Button, {
        className: 'Button Button--danger',
        style: {
          float: 'none'
        },
        loading: true
      }, app.translator.trans('v17development-flarum-badges.admin.auto_moderator.badge_selector.loading_badges')));
    }
    const badge = app.store.getById('badges', this.attrs.value);
    const label = badge ? [badge.icon() && m(Icon, {
      name: badge.icon()
    }), '\t', badge.name()] : app.translator.trans('v17development-flarum-badges.admin.auto_moderator.badge_selector.placeholder');
    return m("div", {
      className: "Form-group"
    }, m("label", null, this.attrs.label), this.attrs.disabled ? m("div", {
      className: "Button Button--danger"
    }, label) : m(Dropdown, {
      label: label,
      disabled: this.attrs.disabled,
      buttonClassName: "Button Button--danger"
    }, app.store.all('badges').map(g => Button.component({
      active: badge && badge.id() === g.id(),
      disabled: badge && badge.id() === g.id(),
      icon: g.icon(),
      onclick: () => {
        this.attrs.onchange(g.id());
      }
    }, g.name()))));
  }
}
flarum.reg.add('v17development-user-badges', 'admin/components/BadgeSelector', BadgeSelector);